      const tt = k * PERIOD / 2;
      const xx = L + pw * tt / tMax;
      gctx.beginPath(); gctx.moveTo(xx, y0 + 4); gctx.lineTo(xx, y0 + ph - 4); gctx.stroke();
      gctx.fillText((k / 2) + 'T', xx, y0 + ph + 9);
