    const xp = L + pw * tp / tMax;
    gctx.strokeStyle = '#444'; gctx.lineWidth = 1;
    gctx.setLineDash([4, 3]);
    gctx.beginPath(); gctx.moveTo(xp, y0 + 4); gctx.lineTo(xp, y0 + ph - 4); gctx.stroke();
    gctx.setLineDash([]);
    const yv = yMid - fn(tp) * sc;
    gctx.fillStyle = color;
    gctx.beginPath(); gctx.arc(xp, yv, 4, 0, Math.PI * 2); gctx.fill();
    // value readout
    gctx.font = 'bold 11px sans-serif'; gctx.textAlign = 'right'; gctx.fillStyle = color;
    gctx.fillText(fn(tp).toFixed(2) + ' ' + unit, L + pw, y0 + 10);
