  }

  panel(TOPPAD + 12, 'Φ(t) = BA cos ωt', '#1F6FD0', B_FIELD * AREA,
    function (t) { return B_FIELD * AREA * Math.cos(OMEGA * t); }, 'Wb');
  panel(TOPPAD + 12 + ph + GAP, 'ε(t) = NBAω sin ωt', '#F07C1E', NTURNS * B_FIELD * AREA * OMEGA,
    function (t) { return NTURNS * B_FIELD * AREA * OMEGA * Math.sin(OMEGA * t); }, 'V');

  gctx.font = '10px sans-serif'; gctx.fillStyle = '#777'; gctx.textAlign = 'center';
  gctx.fillText('time  (T = ' + PERIOD.toFixed(0) + ' s per revolution)', L + pw / 2, h - 4);
}

/* ── apply θ to the whole scene ─────────────────────────────────────────── */
function applyTheta() {
  const th = THREE.MathUtils.degToRad(theta);
  coilGroup.rotation.y = th;
  rebuildArc(theta);

  const nx = Math.cos(th), nz = -Math.sin(th);
  nLabel.pos.set(nx * 1.58, -0.05, nz * 1.58);
  const half = th / 2;
  thLabel.pos.set(0.82 * Math.cos(half), 0.1, -0.82 * Math.sin(half));

  const flux = B_FIELD * AREA * Math.cos(th);
  const emf = NTURNS * B_FIELD * AREA * OMEGA * Math.sin(th);
  elThetaVal.textContent = theta.toFixed(0) + '\u00B0';
  elFlux.textContent = flux.toFixed(2);
  elEmf.textContent = emf.toFixed(2);
  readLabel.div.innerHTML =
    '&theta; = ' + theta.toFixed(0) + '&deg; &nbsp;&middot;&nbsp; ' +
    '<span style="color:#1F6FD0">&Phi; = ' + flux.toFixed(2) + ' Wb</span> &nbsp;&middot;&nbsp; ' +
    '<span style="color:#F07C1E">&epsilon; = ' + emf.toFixed(2) + ' V</span>';
  if (elSlider.value !== String(Math.round(theta))) elSlider.value = String(Math.round(theta));
}

/* ── guided demo ────────────────────────────────────────────────────────── */
const steps = [
  { title: 'Face-on: maximum flux', narr: 'At θ = 0 the orange normal n̂ points straight along B, the coil face is broadside to the field, and the flux reaches its maximum BA.', theta: 0, view: '3D vectors', spin: false },
  { title: 'Tilted coil', narr: 'Drag θ to 35°: only the component of B along n̂ threads the loop, so the flux drops to BA cos 35°.', theta: 35, view: '3D vectors', spin: false },
  { title: 'Edge-on: zero flux', narr: 'At θ = 90° n̂ is perpendicular to B, field lines skim past the coil plane and the flux is zero — yet this is where the flux is changing fastest.', theta: 90, view: '3D vectors', spin: false },
  { title: 'Read the curves', narr: 'Switch to the graph view: Φ traces BA cos θ while ε traces NBAω sin θ, a quarter cycle out of step.', theta: 90, view: 'Flux & emf graphs', spin: false },
  { title: 'Continuous rotation', narr: 'Play the steady spin with both panels shown — the turning angle between n̂ and B is what generates the alternating emf.', view: 'Both', spin: true }
];
let stepIdx = 1;
const tween = { active: false, from: 0, to: 0, t: 0, dur: 0.9 };

function setSpin(on) {
  spinning = on;
  elSpin.classList.toggle('active', spinning);
  elSpin.innerHTML = spinning ? '&#10074;&#10074; Pause rotation' : '&#9654; Rotate coil at constant &omega;';
}

function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepNarr').textContent = s.narr;
  if (s.view) setViewMode(s.view);
  setSpin(!!s.spin);
  if (typeof s.theta === 'number' && !s.spin) {
    tween.active = true; tween.from = theta; tween.to = s.theta; tween.t = 0;
  } else {
    tween.active = false;
  }
}
document.getElementById('nextStep').addEventListener('click', function () { goToStep(stepIdx + 1); });
document.getElementById('prevStep').addEventListener('click', function () { goToStep(stepIdx - 1); });

/* ── update loop ────────────────────────────────────────────────────────── */
let _last = performance.now();
function figTick() {
  requestAnimationFrame(figTick);
  const now = performance.now();
  let dt = (now - _last) / 1000; _last = now;
  if (dt > 0.1) dt = 0.1;

  if (tween.active) {
    tween.t += dt / tween.dur;
    let u = Math.min(1, tween.t);
    u = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    theta = tween.from + (tween.to - tween.from) * u;
    tAccum = theta / DEG_PER_S;
    if (tween.t >= 1) { tween.active = false; theta = tween.to; tAccum = theta / DEG_PER_S; }
    applyTheta();
  } else if (spinning) {
    tAccum += dt;
    theta = (tAccum * DEG_PER_S) % 360;
    applyTheta();
  }
  drawGraphs();
}
applyTheta();
goToStep(1);
figTick();
// @FIGURE_CODE_END

