// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
   coil (5 turns)  → ExtrudeGeometry(rect Shape 2.0×3.0 w/ rect hole, band .12,
                     depth .03) ×5, offsets −.10…+.10 along local normal,
                     alternating #BDBDBD / #F2F2F2, EdgesGeometry #555,
                     inside coilGroup(rotation.y = −θ)  → open window frame
   z axis solid    → Line (0,1.5,0)→(0,3.4,0) and (0,−1.5,0)→(0,−3.2,0) black
   z axis dashed   → LineDashedMaterial (0,−1.5,0)→(0,1.5,0) black
   z label         → addLabel italic bold 'z' above tip
   spin curl       → Line arc r=.45 at y=2.6 in XZ plane + ConeGeometry head
   x axis solid    → cylinder+cone arrow along +Z, length 3.2, black
   x axis dashed   → LineDashedMaterial origin→(0,0,−2.2)
   x label         → addLabel italic bold 'x' at lower-left tip
   y axis stub     → Line (−1.2,0,0)→origin black
   origin          → SphereGeometry(0.055) black
   B vector        → cylinder(r .07)+cone, world +X, length 2.2, blue #1F6FD0
   n-hat vector    → cylinder(r .045)+cone, local +X in coilGroup, len 1.3,
                     orange #F07C1E  → world (cosθ,0,sinθ)
   theta arc       → Line r=.55 in XZ plane, a: 0→θ, black, rebuilt on θ
   readout HUD     → faded HTML card, top-left of stage (not over the figure)
   graph panel     → 2D canvas overlay in #stage, Φ(t) blue / ε(t) orange
   ─────────────────────────────────────────────────────────────────────────
   Axis mapping: figure z → world +Y, figure y (B) → world +X,
                 figure x → world +Z.  n̂ = (cos θ, 0, sin θ)  → drawn
   down-and-right between B and the +x axis, exactly as in the source.
*/

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.88));
const _dl = new THREE.DirectionalLight(0xffffff, 0.45);
_dl.position.set(5, 6, 6);
scene.add(_dl);
const _dl2 = new THREE.DirectionalLight(0xffffff, 0.22);
_dl2.position.set(-5, 2, -6);
scene.add(_dl2);

const BLACK = 0x000000, BLUE = 0x1f6fd0, ORANGE = 0xf07c1e;

/* ── helpers ────────────────────────────────────────────────────────────── */
function solidLine(a, b, color) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  return new THREE.Line(g, new THREE.LineBasicMaterial({ color: color }));
}
function dashedLine(a, b, color) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({ color: color, dashSize: 0.14, gapSize: 0.1 }));
  l.computeLineDistances();
  return l;
}
function makeArrow(dirVec, len, color, shaftR, headR, headL) {
  const grp = new THREE.Group();
  const mat = new THREE.MeshLambertMaterial({ color: color });
  const sl = Math.max(0.01, len - headL);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 22), mat);
  shaft.position.y = sl / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 28), mat);
  head.position.y = sl + headL / 2;
  grp.add(shaft); grp.add(head);
  grp.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dirVec.clone().normalize());
  return grp;
}
function rectRingGeom(w, h, band, depth) {
  const s = new THREE.Shape();
  s.moveTo(-w / 2, -h / 2); s.lineTo(w / 2, -h / 2); s.lineTo(w / 2, h / 2); s.lineTo(-w / 2, h / 2); s.closePath();
  const iw = w / 2 - band, ih = h / 2 - band;
  const hole = new THREE.Path();
  hole.moveTo(-iw, -ih); hole.lineTo(-iw, ih); hole.lineTo(iw, ih); hole.lineTo(iw, -ih); hole.closePath();
  s.holes.push(hole);
  const g = new THREE.ExtrudeGeometry(s, { depth: depth, bevelEnabled: false, curveSegments: 1 });
  g.translate(0, 0, -depth / 2);
  return g;
}

/* ── coil (multi-turn winding, genuinely open window) ───────────────────── */
const coilGroup = new THREE.Group();
scene.add(coilGroup);

const COIL_W = 2.0, COIL_H = 3.0, BAND = 0.12, TURN_D = 0.03;
const offsets = [-0.10, -0.05, 0.0, 0.05, 0.10];
const turnMats = [
  new THREE.MeshLambertMaterial({ color: 0xbdbdbd }),
  new THREE.MeshLambertMaterial({ color: 0xf4f4f4 })
];
const edgeMat = new THREE.LineBasicMaterial({ color: 0x555555 });
const coilMeshes = new THREE.Group();
offsets.forEach(function (off, i) {
  const geom = rectRingGeom(COIL_W, COIL_H, BAND, TURN_D);
  const m = new THREE.Mesh(geom, turnMats[i % 2]);
  m.rotation.y = Math.PI / 2;          // local +Z (coil normal) → world +X
  m.position.x = off;
  const e = new THREE.LineSegments(new THREE.EdgesGeometry(geom, 20), edgeMat);
  m.add(e);
  coilMeshes.add(m);
});
coilGroup.add(coilMeshes);
registerInteractive(coilMeshes, {
  title: 'Multi-turn rectangular coil',
  tooltip: 'N stacked turns, area A = 2.0 m × 3.0 m',
  body: 'The coil is a stack of N identical turns of area A. Each turn links the same flux Φ = B·A·cos θ, so the emfs of the turns add: ε = N·B·A·ω·sin θ.'
});

/* ── n̂ unit normal (rigidly attached to the coil) ───────────────────────── */
const nArrow = makeArrow(new THREE.Vector3(1, 0, 0), 1.3, ORANGE, 0.045, 0.125, 0.32);
coilGroup.add(nArrow);
registerInteractive(nArrow, {
  title: 'Unit normal n̂',
  tooltip: 'Perpendicular to the coil plane',
  body: 'n̂ is perpendicular to the plane of the coil and turns rigidly with it. Only the component of B along n̂ threads the loop, which is why Φ = B·A·cos θ.'
});

/* ── B field vector ─────────────────────────────────────────────────────── */
const bArrow = makeArrow(new THREE.Vector3(1, 0, 0), 2.2, BLUE, 0.07, 0.175, 0.42);
scene.add(bArrow);
registerInteractive(bArrow, {
  title: 'Uniform magnetic field B',
  tooltip: 'Constant, horizontal, fixed in space',
  body: 'The external field B is uniform and fixed in space. All of the time-dependence of the flux comes from the coil turning, not from the field changing.'
});

/* ── axes ───────────────────────────────────────────────────────────────── */
scene.add(solidLine(new THREE.Vector3(0, 1.5, 0), new THREE.Vector3(0, 3.4, 0), BLACK));
scene.add(solidLine(new THREE.Vector3(0, -1.5, 0), new THREE.Vector3(0, -3.2, 0), BLACK));
scene.add(dashedLine(new THREE.Vector3(0, -1.5, 0), new THREE.Vector3(0, 1.5, 0), BLACK));

// figure x-axis: solid toward the viewer's lower-left (+Z), dashed continuation (−Z)
const xAxisArrow = makeArrow(new THREE.Vector3(0, 0, 1), 3.2, BLACK, 0.014, 0.085, 0.28);
scene.add(xAxisArrow);
scene.add(dashedLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, -2.2), BLACK));

// short y-axis stub to screen-left of the origin
scene.add(solidLine(new THREE.Vector3(-1.2, 0, 0), new THREE.Vector3(0, 0, 0), BLACK));

// origin dot
const originDot = new THREE.Mesh(new THREE.SphereGeometry(0.055, 18, 14),
  new THREE.MeshLambertMaterial({ color: BLACK }));
scene.add(originDot);

/* ── rotation curl around the top of the z-axis ─────────────────────────── */
(function () {
  const r = 0.45, y = 2.6, a0 = THREE.MathUtils.degToRad(-30), a1 = THREE.MathUtils.degToRad(275);
  const pts = [];
  for (let i = 0; i <= 72; i++) {
    const a = a0 + (a1 - a0) * i / 72;
    pts.push(new THREE.Vector3(r * Math.cos(a), y, r * Math.sin(a)));
  }
  scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: BLACK })));
  const tan = new THREE.Vector3(-Math.sin(a1), 0, Math.cos(a1)).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.24, 20),
    new THREE.MeshLambertMaterial({ color: BLACK }));
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  head.position.set(r * Math.cos(a1), y, r * Math.sin(a1));
  scene.add(head);
})();

/* ── theta arc (rebuilt whenever θ changes) ─────────────────────────────── */
const arcMat = new THREE.LineBasicMaterial({ color: BLACK });
let thetaArc = new THREE.Line(new THREE.BufferGeometry(), arcMat);
scene.add(thetaArc);
function rebuildArc(thDeg) {
  const R = 0.62;
  const n = Math.max(2, Math.round(Math.abs(thDeg) / 3) + 2);
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = THREE.MathUtils.degToRad(thDeg * i / (n - 1));
    pts.push(new THREE.Vector3(R * Math.cos(a), 0, R * Math.sin(a)));
  }
  const old = thetaArc.geometry;
  thetaArc.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (old) old.dispose();
}
rebuildArc(35);

/* ── state (declared before the camera helper uses viewMode) ────────────── */
let theta = 35;                 // degrees
let viewMode = '3D vectors';

/* ── camera: broadside coil face, B projecting ~horizontally right ──────── */
