   x label         → addLabel italic bold 'x' at lower-left tip
   y axis stub     → Line (−1.2,0,0)→origin black
   origin          → SphereGeometry(0.055) black
   B vector        → cylinder(r .07)+cone, world +X, length 2.2, blue #1F6FD0
   n-hat vector    → cylinder(r .045)+cone, local +X in coilGroup, len 1.3,
                     orange #F07C1E  → world (cosθ,0,sinθ)
   theta arc       → Line r=.55 in XZ plane, a: 0→θ, black, rebuilt on θ
   readout HUD     → faded HTML card, top-left of stage (not over the figure)
   graph panel     → 2D canvas overlay in #stage, Φ(t) blue / ε(t) orange
   ─────────────────────────────────────────────────────────────────────────
   Axis mapping: figure z → world +Y, figure y (B) → world +X,
                 figure x → world +Z.  n̂ = (cos θ, 0, sin θ)  → drawn
   down-and-right between B and the +x axis, exactly as in the source.
*/

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.88));
const _dl = new THREE.DirectionalLight(0xffffff, 0.45);
_dl.position.set(5, 6, 6);
scene.add(_dl);
const _dl2 = new THREE.DirectionalLight(0xffffff, 0.22);
_dl2.position.set(-5, 2, -6);
scene.add(_dl2);

const BLACK = 0x000000, BLUE = 0x1f6fd0, ORANGE = 0xf07c1e;

/* ── helpers ────────────────────────────────────────────────────────────── */
function solidLine(a, b, color) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  return new THREE.Line(g, new THREE.LineBasicMaterial({ color: color }));
}
function dashedLine(a, b, color) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({ color: color, dashSize: 0.14, gapSize: 0.1 }));
  l.computeLineDistances();
  return l;
}
function makeArrow(dirVec, len, color, shaftR, headR, headL) {
  const grp = new THREE.Group();
  const mat = new THREE.MeshLambertMaterial({ color: color });
  const sl = Math.max(0.01, len - headL);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 22), mat);
  shaft.position.y = sl / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 28), mat);
  head.position.y = sl + headL / 2;
  grp.add(shaft); grp.add(head);
  grp.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dirVec.clone().normalize());
  return grp;
}
function rectRingGeom(w, h, band, depth) {
  const s = new THREE.Shape();
  s.moveTo(-w / 2, -h / 2); s.lineTo(w / 2, -h / 2); s.lineTo(w / 2, h / 2); s.lineTo(-w / 2, h / 2); s.closePath();
  const iw = w / 2 - band, ih = h / 2 - band;
  const hole = new THREE.Path();
  hole.moveTo(-iw, -ih); hole.lineTo(-iw, ih); hole.lineTo(iw, ih); hole.lineTo(iw, -ih); hole.closePath();
  s.holes.push(hole);
  const g = new THREE.ExtrudeGeometry(s, { depth: depth, bevelEnabled: false, curveSegments: 1 });
  g.translate(0, 0, -depth / 2);
  return g;
}

/* ── coil (multi-turn winding, genuinely open window) ───────────────────── */
const coilGroup = new THREE.Group();
scene.add(coilGroup);

const COIL_W = 2.0, COIL_H = 3.0, BAND = 0.12, TURN_D = 0.03;
const offsets = [-0.10, -0.05, 0.0, 0.05, 0.10];
const turnMats = [
  new THREE.MeshLambertMaterial({ color: 0xbdbdbd }),
  new THREE.MeshLambertMaterial({ color: 0xf4f4f4 })
];
const edgeMat = new THREE.LineBasicMaterial({ color: 0x555555 });
const coilMeshes = new THREE.Group();
offsets.forEach(function (off, i) {
  const geom = rectRingGeom(COIL_W, COIL_H, BAND, TURN_D);
  const m = new THREE.Mesh(geom, turnMats[i % 2]);
  m.rotation.y = Math.PI / 2;          // local +Z (coil normal) → world +X
  m.position.x = off;
  const e = new THREE.LineSegments(new THREE.EdgesGeometry(geom, 20), edgeMat);
  m.add(e);
  coilMeshes.add(m);
});
coilGroup.add(coilMeshes);
registerInteractive(coilMeshes, {
  title: 'Multi-turn rectangular coil',
  tooltip: 'N stacked turns, area A = 2.0 m × 3.0 m',
  body: 'The coil is a stack of N identical turns of area A. Each turn links the same flux Φ = B·A·cos θ, so the emfs of the turns add: ε = N·B·A·ω·sin θ.'
});

/* ── n̂ unit normal (rigidly attached to the coil) ───────────────────────── */
const nArrow = makeArrow(new THREE.Vector3(1, 0, 0), 1.3, ORANGE, 0.045, 0.125, 0.32);
coilGroup.add(nArrow);
registerInteractive(nArrow, {
  title: 'Unit normal n̂',
  tooltip: 'Perpendicular to the coil plane',
  body: 'n̂ is perpendicular to the plane of the coil and turns rigidly with it. Only the component of B along n̂ threads the loop, which is why Φ = B·A·cos θ.'
});

/* ── B field vector ─────────────────────────────────────────────────────── */
const bArrow = makeArrow(new THREE.Vector3(1, 0, 0), 2.2, BLUE, 0.07, 0.175, 0.42);
scene.add(bArrow);
registerInteractive(bArrow, {
  title: 'Uniform magnetic field B',
  tooltip: 'Constant, horizontal, fixed in space',
  body: 'The external field B is uniform and fixed in space. All of the time-dependence of the flux comes from the coil turning, not from the field changing.'
});

/* ── axes ───────────────────────────────────────────────────────────────── */
scene.add(solidLine(new THREE.Vector3(0, 1.5, 0), new THREE.Vector3(0, 3.4, 0), BLACK));
scene.add(solidLine(new THREE.Vector3(0, -1.5, 0), new THREE.Vector3(0, -3.2, 0), BLACK));
scene.add(dashedLine(new THREE.Vector3(0, -1.5, 0), new THREE.Vector3(0, 1.5, 0), BLACK));

// figure x-axis: solid toward the viewer's lower-left (+Z), dashed continuation (−Z)
const xAxisArrow = makeArrow(new THREE.Vector3(0, 0, 1), 3.2, BLACK, 0.014, 0.085, 0.28);
scene.add(xAxisArrow);
scene.add(dashedLine(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, -2.2), BLACK));

// short y-axis stub to screen-left of the origin
scene.add(solidLine(new THREE.Vector3(-1.2, 0, 0), new THREE.Vector3(0, 0, 0), BLACK));

// origin dot
const originDot = new THREE.Mesh(new THREE.SphereGeometry(0.055, 18, 14),
  new THREE.MeshLambertMaterial({ color: BLACK }));
scene.add(originDot);

/* ── rotation curl around the top of the z-axis ─────────────────────────── */
(function () {
  const r = 0.45, y = 2.6, a0 = THREE.MathUtils.degToRad(-30), a1 = THREE.MathUtils.degToRad(275);
  const pts = [];
  for (let i = 0; i <= 72; i++) {
    const a = a0 + (a1 - a0) * i / 72;
    pts.push(new THREE.Vector3(r * Math.cos(a), y, r * Math.sin(a)));
  }
  scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: BLACK })));
  const tan = new THREE.Vector3(-Math.sin(a1), 0, Math.cos(a1)).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.24, 20),
    new THREE.MeshLambertMaterial({ color: BLACK }));
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  head.position.set(r * Math.cos(a1), y, r * Math.sin(a1));
  scene.add(head);
})();

/* ── theta arc (rebuilt whenever θ changes) ─────────────────────────────── */
const arcMat = new THREE.LineBasicMaterial({ color: BLACK });
let thetaArc = new THREE.Line(new THREE.BufferGeometry(), arcMat);
scene.add(thetaArc);
function rebuildArc(thDeg) {
  const R = 0.62;
  const n = Math.max(2, Math.round(Math.abs(thDeg) / 3) + 2);
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = THREE.MathUtils.degToRad(thDeg * i / (n - 1));
    pts.push(new THREE.Vector3(R * Math.cos(a), 0, R * Math.sin(a)));
  }
  const old = thetaArc.geometry;
  thetaArc.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (old) old.dispose();
}
rebuildArc(35);

/* ── state (declared before the camera helper uses viewMode) ────────────── */
let theta = 35;                 // degrees
let viewMode = '3D vectors';

/* ── camera: broadside coil face, B projecting ~horizontally right ──────── */
function applyCamera() {
  const hf = (viewMode === 'Both') ? 0.62 : 0.80;
  setCameraView({
    projection: 'perspective',
    azimuthDeg: 45,
    elevationDeg: 20,
    rollDeg: 0,
    heightFraction: hf,
    target: [0, 0, 0],
    distanceScale: 1.2
  });
  if (viewMode === 'Both') {
    // slide the figure into the left portion so the graph panel does not cover it
    const right = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 0).normalize();
    const dist = camera.position.distanceTo(controls.target);
    const shift = dist * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * aspect * 0.24;
    camera.position.addScaledVector(right, shift);
    controls.target.addScaledVector(right, shift);
    camera.updateProjectionMatrix();
    controls.update();
  }
}
applyCamera();

/* ── labels (sized for the perspective label scaling ≈0.6) ──────────────── */
addLabel('<i><b>z</b></i>', new THREE.Vector3(0, 3.5, 0),
  { fontSize: '30px', offset: [0, -16] });
addLabel('<i><b>x</b></i>', new THREE.Vector3(0, 0, 3.3),
  { fontSize: '30px', offset: [-14, 20] });
addLabel('<b><i>B</i></b>&#8407;', new THREE.Vector3(2.25, 0, 0),
  { fontSize: '36px', color: '#1F6FD0', bold: true, offset: [32, -10] });
const nLabel = addLabel('<b>n&#770;</b>', new THREE.Vector3(1.55, 0, 0),
  { fontSize: '34px', color: '#F07C1E', bold: true, offset: [10, 20] });
const thLabel = addLabel('<i>&theta;</i>', new THREE.Vector3(0.9, 0.05, 0.2),
  { fontSize: '30px', offset: [6, -4] });

/* ── physics constants ──────────────────────────────────────────────────── */
const B_FIELD = 1.0, AREA = 1.0, NTURNS = 1.0;
const PERIOD = 6.0;                       // s per revolution
const OMEGA = 2 * Math.PI / PERIOD;       // rad/s
const DEG_PER_S = 360 / PERIOD;

let tAccum = 35 / DEG_PER_S;
let spinning = false;

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const elSlider = document.getElementById('thetaAngle');
const elThetaVal = document.getElementById('thetaVal');
const elFlux = document.getElementById('fluxVal');
const elEmf = document.getElementById('emfVal');
const elSpin = document.getElementById('spin');
const btnReset = document.getElementById('btnReset');
btnReset.style.display = '';
btnReset.textContent = 'Reset view';
btnReset.addEventListener('click', function () { applyCamera(); });

elSlider.addEventListener('input', function () {
  theta = parseFloat(elSlider.value);
  tAccum = theta / DEG_PER_S;
  tween.active = false;
  applyTheta();
});

elSpin.addEventListener('click', function () { setSpin(!spinning); });

const viewBtns = {
  '3D vectors': document.getElementById('view3d'),
  'Flux & emf graphs': document.getElementById('viewGraph'),
  'Both': document.getElementById('viewBoth')
};
Object.keys(viewBtns).forEach(function (k) {
  viewBtns[k].addEventListener('click', function () { setViewMode(k); });
});

/* ── faded readout HUD, top-left of the stage (out of the figure's way) ─── */
const stageEl = document.getElementById('stage');
const hud = document.createElement('div');
hud.style.cssText = 'position:absolute;top:10px;left:12px;z-index:6;pointer-events:none;' +
  'font:12px/1.6 sans-serif;color:#555;background:rgba(255,255,255,0.72);' +
  'padding:5px 9px;border-radius:5px;opacity:0.85;';
stageEl.appendChild(hud);

/* ── graph overlay canvas ───────────────────────────────────────────────── */
const gcv = document.createElement('canvas');
gcv.id = 'graphCanvas';
gcv.style.cssText = 'position:absolute;top:0;right:0;height:100%;width:40%;background:#ffffff;' +
  'z-index:5;display:none;box-sizing:border-box;pointer-events:none;';
stageEl.appendChild(gcv);
const gctx = gcv.getContext('2d');

function setViewMode(mode) {
  const changed = (mode !== viewMode);
  viewMode = mode;
  Object.keys(viewBtns).forEach(function (k) { viewBtns[k].classList.toggle('active', k === mode); });
  if (mode === '3D vectors') {
    gcv.style.display = 'none';
  } else if (mode === 'Flux & emf graphs') {
    gcv.style.display = 'block';
    gcv.style.width = '100%';
    gcv.style.borderLeft = 'none';
  } else {
    gcv.style.display = 'block';
    gcv.style.width = '40%';
    gcv.style.borderLeft = '1px solid #dcdfe3';
  }
  if (changed) applyCamera();
}

function drawGraphs() {
  if (gcv.style.display === 'none') return;
  const w = gcv.clientWidth, h = gcv.clientHeight;
  if (!w || !h) return;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  if (gcv.width !== Math.round(w * dpr) || gcv.height !== Math.round(h * dpr)) {
    gcv.width = Math.round(w * dpr); gcv.height = Math.round(h * dpr);
  }
  gctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  gctx.clearRect(0, 0, w, h);
  gctx.fillStyle = '#ffffff';
  gctx.fillRect(0, 0, w, h);

  const L = 48, R = 16, TOPPAD = 14, GAP = 26;
  const pw = Math.max(20, w - L - R);
  const ph = Math.max(30, (h - TOPPAD * 2 - GAP) / 2);
  const tMax = 2 * PERIOD;
  const tp = ((tAccum % tMax) + tMax) % tMax;

  function panel(y0, title, color, amp, fn, unit) {
    const yMid = y0 + ph / 2;
    const sc = (ph / 2 - 16) / amp;
    gctx.font = 'bold 13px sans-serif';
    gctx.fillStyle = color;
    gctx.textAlign = 'left';
    gctx.fillText(title, L, y0 - 3);
    gctx.strokeStyle = '#bbb'; gctx.lineWidth = 1;
    gctx.beginPath(); gctx.moveTo(L, yMid); gctx.lineTo(L + pw, yMid); gctx.stroke();
    gctx.beginPath(); gctx.moveTo(L, y0 + 4); gctx.lineTo(L, y0 + ph - 4); gctx.stroke();
    gctx.strokeStyle = '#ececec';
    gctx.font = '10px sans-serif'; gctx.fillStyle = '#888'; gctx.textAlign = 'center';
    for (let k = 0; k <= 4; k++) {
      const tt = k * PERIOD / 2;
      const xx = L + pw * tt / tMax;
      gctx.beginPath(); gctx.moveTo(xx, y0 + 4); gctx.lineTo(xx, y0 + ph - 4); gctx.stroke();
      gctx.fillText((k / 2) + 'T', xx, y0 + ph + 11);
    }
    gctx.strokeStyle = color; gctx.lineWidth = 2;
    gctx.beginPath();
    for (let i = 0; i <= 240; i++) {
      const tt = tMax * i / 240;
      const xx = L + pw * i / 240;
      const yy = yMid - fn(tt) * sc;
      if (i === 0) gctx.moveTo(xx, yy); else gctx.lineTo(xx, yy);
    }
    gctx.stroke();
    gctx.font = '10px sans-serif'; gctx.fillStyle = '#666'; gctx.textAlign = 'right';
    gctx.fillText(amp.toFixed(2), L - 5, yMid - (ph / 2 - 16) + 3);
    gctx.fillText('0', L - 5, yMid + 3);
    const xp = L + pw * tp / tMax;
    gctx.strokeStyle = '#444'; gctx.lineWidth = 1;
    gctx.setLineDash([4, 3]);
    gctx.beginPath(); gctx.moveTo(xp, y0 + 4); gctx.lineTo(xp, y0 + ph - 4); gctx.stroke();
    gctx.setLineDash([]);
    const yv = yMid - fn(tp) * sc;
    gctx.fillStyle = color;
    gctx.beginPath(); gctx.arc(xp, yv, 4.5, 0, Math.PI * 2); gctx.fill();
    gctx.font = 'bold 12px sans-serif'; gctx.textAlign = 'right'; gctx.fillStyle = color;
    gctx.fillText(fn(tp).toFixed(2) + ' ' + unit, L + pw, y0 + 11);
  }

  panel(TOPPAD + 12, 'Φ(t) = BA cos ωt', '#1F6FD0', B_FIELD * AREA,
    function (t) { return B_FIELD * AREA * Math.cos(OMEGA * t); }, 'Wb');
  panel(TOPPAD + 12 + ph + GAP, 'ε(t) = NBAω sin ωt', '#F07C1E', NTURNS * B_FIELD * AREA * OMEGA,
    function (t) { return NTURNS * B_FIELD * AREA * OMEGA * Math.sin(OMEGA * t); }, 'V');

  gctx.font = '11px sans-serif'; gctx.fillStyle = '#777'; gctx.textAlign = 'center';
  gctx.fillText('time  (T = ' + PERIOD.toFixed(0) + ' s per revolution)', L + pw / 2, h - 5);
}

/* ── apply θ to the whole scene ─────────────────────────────────────────── */
function applyTheta() {
  const th = THREE.MathUtils.degToRad(theta);
  coilGroup.rotation.y = -th;              // local +X → world (cos θ, 0, sin θ)
  rebuildArc(theta);

  const nx = Math.cos(th), nz = Math.sin(th);
  nLabel.pos.set(nx * 1.58, -0.06, nz * 1.58);
  const half = th / 2;
  thLabel.pos.set(0.92 * Math.cos(half), 0.1, 0.92 * Math.sin(half));

  const flux = B_FIELD * AREA * Math.cos(th);
  const emf = NTURNS * B_FIELD * AREA * OMEGA * Math.sin(th);
  elThetaVal.textContent = theta.toFixed(0) + '\u00B0';
  elFlux.textContent = flux.toFixed(2);
  elEmf.textContent = emf.toFixed(2);
  hud.innerHTML =
    '&theta; = <b>' + theta.toFixed(0) + '&deg;</b><br>' +
    '<span style="color:#1F6FD0">&Phi; = BA cos&thinsp;&theta; = ' + flux.toFixed(2) + ' Wb</span><br>' +
    '<span style="color:#F07C1E">&epsilon; = NBA&omega; sin&thinsp;&theta; = ' + emf.toFixed(2) + ' V</span>';
  if (elSlider.value !== String(Math.round(theta))) elSlider.value = String(Math.round(theta));
}

/* ── guided demo ────────────────────────────────────────────────────────── */
const steps = [
  { title: 'Face-on: maximum flux', narr: 'At θ = 0 the orange normal n̂ points straight along B, the coil face is broadside to the field, and the flux reaches its maximum BA.', theta: 0, view: '3D vectors', spin: false },
  { title: 'Tilted coil', narr: 'Drag θ to 35°: only the component of B along n̂ threads the loop, so the flux drops to BA cos 35°.', theta: 35, view: '3D vectors', spin: false },
  { title: 'Edge-on: zero flux', narr: 'At θ = 90° n̂ is perpendicular to B, field lines skim past the coil plane and the flux is zero — yet this is where the flux is changing fastest.', theta: 90, view: '3D vectors', spin: false },
  { title: 'Read the curves', narr: 'Switch to the graph view: Φ traces BA cos θ while ε traces NBAω sin θ, a quarter cycle out of step.', theta: 90, view: 'Flux & emf graphs', spin: false },
  { title: 'Continuous rotation', narr: 'Play the steady spin with both panels shown — the turning angle between n̂ and B is what generates the alternating emf.', view: 'Both', spin: true }
];
let stepIdx = 1;
const tween = { active: false, from: 0, to: 0, t: 0, dur: 0.9 };

function setSpin(on) {
  spinning = on;
  if (spinning) tween.active = false;
  elSpin.classList.toggle('active', spinning);
  elSpin.innerHTML = spinning ? '&#10074;&#10074; Pause rotation' : '&#9654; Rotate coil at constant &omega;';
}

function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepNarr').textContent = s.narr;
  if (s.view) setViewMode(s.view);
  setSpin(!!s.spin);
  if (typeof s.theta === 'number' && !s.spin) {
    tween.active = true; tween.from = theta; tween.to = s.theta; tween.t = 0;
  } else {
    tween.active = false;
  }
}
document.getElementById('nextStep').addEventListener('click', function () { goToStep(stepIdx + 1); });
document.getElementById('prevStep').addEventListener('click', function () { goToStep(stepIdx - 1); });

/* ── update loop ────────────────────────────────────────────────────────── */
let _last = performance.now();
function figTick() {
  requestAnimationFrame(figTick);
  const now = performance.now();
  let dt = (now - _last) / 1000; _last = now;
  if (dt > 0.1) dt = 0.1;

  if (tween.active) {
    tween.t += dt / tween.dur;
    let u = Math.min(1, tween.t);
    u = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    theta = tween.from + (tween.to - tween.from) * u;
    tAccum = theta / DEG_PER_S;
    if (tween.t >= 1) { tween.active = false; theta = tween.to; tAccum = theta / DEG_PER_S; }
    applyTheta();
  } else if (spinning) {
    tAccum += dt;
    theta = (tAccum * DEG_PER_S) % 360;
    applyTheta();
  }
  drawGraphs();
}
applyTheta();
goToStep(1);
figTick();
// @FIGURE_CODE_END

